insert into public.exercises(id,owner_id,name,name_ar,equipment,equipment_ar,instructions,instructions_ar,movement,kind,media_url,media_ref,category,body_part,target_muscle) values
('wger-12',NULL,'Seated Hip Adduction','','Hip adduction machine','جهاز ضم الفخذين','Adjust the thigh pads and sit upright with your back against the support. Begin with your knees apart and the pads against the inside of your thighs. Hold the handles, bring your knees together under control, pause briefly, then let the pads return slowly.','','upper legs','strength','',NULL,'upper legs','upper legs','unspecified'),
('wger-46',NULL,'Barbell Lunges Standing','','Barbell','بار حديد','Put barbell on the back of your shoulders. Stand upright, then take the first step forward. Step should bring you forward so that your supporting legs knee can touch the floor. Then stand back up and repeat with the other leg. Remember to keep good posture.','','upper legs','strength','',NULL,'upper legs','upper legs','Quads'),
('wger-73',NULL,'Bench Press','','Barbell, Bench','بار حديد، مقعد','Lay down on a bench, the bar should be directly above your eyes, the knees are somewhat angled and the feet are firmly on the floor. Concentrate, breath deeply and grab the bar more than shoulder wide. Bring it slowly down till it briefly touches your chest at the height of your nipples. Push the bar up. If you train with a high weight it is advisable to have a spotter that can help you up if you can''t lift the weight on your own. With the width of the grip you can also control which part of the chest is trained more: wide grip: outer chest muscles narrow grip: inner chest muscles and triceps','','chest','strength','',NULL,'chest','chest','Chest'),
('wger-75',NULL,'Dumbbell Bench Press','','Bench, Dumbbell','مقعد، دمبل','Setup and Starting Position: Sit at the end of a flat bench with a dumbbell resting vertically against each thigh. Carefully lean back while driving the dumbbells toward your chest with your knees. The “Leg Drive” and Posture: Plant your feet firmly on the floor. Retract your shoulder blades (press them together against the bench) and maintain a slight natural lumbar curve. Starting Position: Push the dumbbells toward the ceiling. Your wrists should be aligned with your elbows. Rotate the dumbbells slightly inward (about 45 degrees) so that your elbows do not splay out too far to the sides, thereby protecting your shoulders. Eccentric Phase (Lowering): Lower the dumbbells in a controlled manner toward the sides of your chest. Your elbows should lower at an angle of about 45–60 degrees relative to your body. Feel the stretch in the lower part of your chest. Concentric Phase (Lift): Push the weight upward in a slight arc (toward the center), without letting the dumbbells collide at the top or fully locking out your elbows to maintain muscle tension. Exhale as you lift. Translated with DeepL.com (free version)','','chest','strength','',NULL,'chest','chest','Chest'),
('wger-82',NULL,'Bent-over Lateral Raises','','Bench, Dumbbell','مقعد، دمبل','Sit on bench while holding weights. Bend forward as far as possible, with arms slightly bent at the elbow. Perform a lateral raise while maintaining the bend in your elbow.','','shoulders','strength','',NULL,'shoulders','shoulders','unspecified'),
('wger-91',NULL,'Biceps Curls With Barbell','','Barbell','بار حديد','Hold the Barbell shoulder-wide, the back is straight, the shoulders slightly back, the arms are streched. Bend the arms, bringing the weight up, with a fast movement. Without pausing, let down the bar with a slow and controlled movement. Don''t allow your body to swing during the exercise, all work is done by the biceps, which are the only mucles that should move (pay attention to the elbows).','','upper arms','strength','',NULL,'upper arms','upper arms','Biceps'),
('wger-92',NULL,'Biceps Curls With Dumbbell','','Dumbbell','دمبل','Hold two dumbbells, the arms are streched, the hands are on your side, the palms face inwards. Bend the arms and bring the weight with a fast movement up. At the same time, rotate your arms by 90 degrees at the very beginning of the movement. At the highest point, rotate a little the weights further outwards. Without a pause, bring them down, slowly. Don''t allow your body to swing during the exercise, all work is done by the biceps, which are the only mucles that should move (pay attention to the elbows).','','upper arms','strength','',NULL,'upper arms','upper arms','Biceps'),
('wger-95',NULL,'Biceps Curl With Cable','','Cable machine','جهاز كابل','Stand around 30 - 40cm away from the cable, the feet are firmly on the floor. Take the bar and lift the weight with a fast movements. Lower the weight as with the dumbbell curls slowly and controlled.','','upper arms','strength','',NULL,'upper arms','upper arms','Biceps'),
('wger-194',NULL,'Dips','','none (bodyweight exercise)','وزن الجسم','Support yourself on parallel bars with your arms straight. Lower under control by bending your elbows until you reach a comfortable depth, keeping your shoulders stable. Press through the bars to return to the start without swinging.','','chest','strength','',NULL,'chest','chest','Chest, Triceps'),
('wger-205',NULL,'Dumbbell Lunges Standing','','Dumbbell','دمبل','Stand tall holding a dumbbell at each side. Step forward and lower under control until both knees are comfortably bent and the rear knee approaches the floor. Drive through the front foot to return to standing, then repeat on the other side while keeping your torso upright.','','upper legs','strength','',NULL,'upper legs','upper legs','Quads'),
('wger-206',NULL,'Dumbbell Lunges Walking','','Dumbbell','دمبل','Starting Position: Stand with feet hip-width apart and hands either on your hips or holding dumbbells at your sides. The Stride: Take a wide step forward with your right leg. The Descent: Lower your hips until both knees are bent at approximately 90-degree angles . The Transition: Drive through your front heel to stand up, bringing your back foot forward to step directly into the next lunge.','','upper legs','strength','',NULL,'upper legs','upper legs','Quads'),
('wger-211',NULL,'Seated Dumbbell Overhead Triceps Extension','','Bench, Dumbbell','مقعد، دمبل','Position one dumbbell over head with both hands under inner plate (heart shaped grip). With elbows over head, lower forearm behind upper arm by flexing elbows. Flex wrists at bottom to avoid hitting dumbbell on back of neck. Raise dumbbell over head by extending elbows while hyperextending wrists. Return and repeat.','','upper arms','strength','',NULL,'upper arms','upper arms','Triceps'),
('wger-222',NULL,'Facepull','','Cable machine','جهاز كابل','Attach a rope to a pulley station set at about chest level. Step back so you''re supporting the weight with arms completely outstretched and assume a staggered (one foot forward) stance. Bend the knees slightly for a stable base. Retract the scapulae (squeeze your partner''s finger with your shoulder blades) and pull the center of the rope slightly up towards the face. A good cue is to think about pulling the ends of the rope apart, not just pulling back. As you near your face, externally rotate so your knuckles are facing the ceiling. Hold for one second at the top position and slowly lower.','','shoulders','strength','',NULL,'shoulders','shoulders','Trapezius'),
('wger-245',NULL,'Skullcrusher Dumbbells','','Bench, Dumbbell','مقعد، دمبل','Hold the dumbbells and lay down on a flat bench in such a way that around 1/4 of your head is over the edge. Stretch arms straight up and then lean dumbbells away from your toes to a 10-20 degree angle. Keep upper arm at this angle throughout exercise. Dumbbell shall not be amed at your head, but away over your head. This will maximise gain from exercise with load on triceps all the time. Pay attention to your elbows and arms: only the triceps are doing the work, the rest of the arms should not move.','','upper arms','strength','',NULL,'upper arms','upper arms','Triceps'),
('wger-246',NULL,'EZ-Bar Skull Crusher','','Bench, SZ-Bar','مقعد، بار إي زد','Hold the SZ-bar and lay down on a flat bench in such a way that around 1/4 of your head is over the edge. Stretch your arms with the bar and bend them so that the bar is lowered. Just before it touches your forehead, push it up. Pay attention to your elbows and arms: only the triceps are doing the work, the rest of the arms should not move.','','upper arms','strength','',NULL,'upper arms','upper arms','Triceps'),
('wger-257',NULL,'Front Squats','','Barbell','بار حديد','Rest the bar across the front of your shoulders and keep your elbows lifted. Stand about shoulder-width apart, brace your torso, and bend your hips and knees to lower under control. Keep your knees tracking with your toes, then drive through your feet to stand.','','upper legs','strength','',NULL,'upper legs','upper legs','Glutes'),
('wger-272',NULL,'Hammer Curls','','Dumbbell','دمبل','Start: Hold dumbbells at your sides with palms facing your torso. Curl: Lift the weights toward your shoulders while maintaining the neutral grip (like holding a hammer). Squeeze: Contract the biceps at the top without moving your elbows forward. Lower: Slowly return to the starting position with full control.','','upper arms','strength','',NULL,'upper arms','upper arms','Biceps'),
('wger-275',NULL,'Cable Hammer Curl','','Cable machine','جهاز كابل','Take a cable in your hands (palms parallel, point to each other), the body is straight. Bend the arms and bring the weight up with a fast movement. Without any pause bring it back down with a slow, controlled movement, but don''t stretch completely your arms. Don''t swing your body during the exercise, the biceps should do all the work here. The elbows are at your side and don''t move.','','upper arms','strength','',NULL,'upper arms','upper arms','Biceps'),
('wger-294',NULL,'Hip Thrust','','Barbell, Bench','بار حديد، مقعد','The bar should go directly on your upper thigh, directly below your crotch. Your feet should be directly under your knees. Push your hips up so that you form a straight line from your knees to your shoulders. Use a pad for comfort.','','upper legs','strength','',NULL,'upper legs','upper legs','Glutes'),
('wger-341',NULL,'Smith Machine Squat','','Smith machine','جهاز سميث','Set the bar around shoulder height and position it across your upper back. Stand about shoulder-width apart with your toes slightly outward. Unrack the bar, brace your torso, and bend your hips and knees to lower under control to a comfortable depth. Drive through your feet to stand, stopping short of forcefully locking your knees. Keep your knees tracking in the same direction as your toes.','','upper legs','strength','',NULL,'upper legs','upper legs','Quads'),
('wger-348',NULL,'Lateral Raises','','Dumbbell','دمبل','This exercise works the deltoid muscle of the shoulder. The movement starts with the arms straight, and the hands holding weights at the sides or in front of the body. Body is in a slight forward-leaning position with hips and knees bent a little. Arms are kept straight or slightly bent, and raised through an arc of movement in the coronal plane that terminates when the hands are at approximately shoulder height. Weights are lowered to the starting position, completing one rep. When using a cable machine the individual stands with the coronal plane in line with the pulley, which is at or near the ground.[9] The exercise can be completed one shoulder at a time (with the other hand used to stabilize the body against the weight moved), or with both hands simultaneously if two parallel pulleys are available.','','shoulders','strength','',NULL,'shoulders','shoulders','Shoulders'),
('wger-349',NULL,'Single-Arm Cable Lateral Raise','','Cable machine','جهاز كابل','Set a cable pulley low and stand side-on to it. Hold the handle with the outside hand, keep a soft bend in the elbow, and raise the arm out to the side to about shoulder height. Lower under control and repeat before changing sides.','','shoulders','strength','',NULL,'shoulders','shoulders','Shoulders'),
('wger-365',NULL,'Lying Leg Curl','','Lying leg curl machine','جهاز ثني الساقين بوضع الاستلقاء','Lay on a bench and put your calves behind the leg holder (better if they are hold on around the lower calves). Hold a grip on the bars to make sure the body is firmly in place. Bend your legs bringing the weight up, go slowly back. During the exercise the body should not move, all work is done by the legs.','','upper legs','strength','',NULL,'upper legs','upper legs','Hamstrings'),
('wger-366',NULL,'Seated Leg Curl','','Seated leg curl machine','جهاز ثني الساقين بوضع الجلوس','Adjust the machine lever to suit your height. Sit with your back against the back pad, place your ankles against the roller pads, and secure your thighs beneath the restraint just above your knees. Hold the handles. Bend your knees while keeping your back and hips still. Pause briefly in the contracted position, then return slowly to the starting position.','','upper legs','strength','',NULL,'upper legs','upper legs','Hamstrings'),
('wger-367',NULL,'Standing Single-Leg Curl','','Standing leg curl machine','جهاز ثني الساق واقفًا','Work one leg at a time. Stand at the machine with the pad positioned against your lower leg just below the calf. Bend your knee until it reaches roughly a right angle, then lower the weight slowly and under control.','','upper legs','strength','',NULL,'upper legs','upper legs','Hamstrings'),
('wger-371',NULL,'45-Degree Leg Press','','Leg press machine','جهاز ضغط الساقين','Sit with your back and head supported and place your feet about shoulder-width apart on the platform. Release the safeties, lower the platform under control until your knees reach a comfortable bend, then press it away without forcefully locking your knees. Keep your feet flat and your back supported.','','upper legs','strength','',NULL,'upper legs','upper legs','Hamstrings, Calves, Glutes, Quads'),
('wger-374',NULL,'Wide-Stance Leg Press','','Leg press machine','جهاز ضغط الساقين','Sit on the machine and put your feet on the platform, a bit more than shoulder wide. The feet are turned outwards by a few degrees. Lower the weight so much, that the knees form a right angle. Push immediately the platform up again, without any pause. When in the lower position, the knees point a bit outwards and the movement should be always fluid.','','upper legs','strength','',NULL,'upper legs','upper legs','Quads'),
('wger-375',NULL,'Hack Squat Machine','','Hack squat machine','جهاز هاك سكوات','Position yourself in the Hackenschmidt machine with your shoulders against the pads. Place your feet about shoulder-width apart with your toes slightly outward. Bend your knees and lower under control until they form an angle of about 90 degrees. Press back up and repeat, without forcefully locking your knees.','','upper legs','strength','',NULL,'upper legs','upper legs','Quads'),
('wger-465',NULL,'EZ-Bar Preacher Curl','','EZ bar, Preacher bench','بار متعرج، مقعد بريتشر','Place the EZ curl bar on the rest handles in front of the preacher bench. Lean over the bench and grab the EZ curl bar with palms up. Sit down on the preacher bench seat so your upper arms rest on top of the pad and your chest is pressed against the pad. Lower the weight until your elbows are extended and arms are straight. Bring the weights back up to the starting point by contracting biceps. Repeat','','upper arms','strength','',NULL,'upper arms','upper arms','Brachialis'),
('wger-475',NULL,'Pull-ups','','Pull-up bar','بار عقلة','Grab the pull up bar with a wide grip, the body is hanging freely. Keep your chest out and pull yourself up till your chin reaches the bar or it touches your neck, if you want to pull behind you. Go with a slow and controlled movement down, always keeping the chest out.','','back','strength','',NULL,'back','back','Lats'),
('wger-477',NULL,'Assisted Pull-Up Machine','','Assisted pull-up machine','جهاز العقلة المساعد','Set the machine to the assistance you need. Position yourself on the platform or knee pad and grip the handles about shoulder-width apart with your arms extended. Bend your elbows and pull your body upward until your chin passes the handles or bar. Lower under control until your arms are extended again. Reduce the assistance gradually as your strength improves.','','back','strength','',NULL,'back','back','Lats'),
('wger-507',NULL,'Romanian Deadlift','','Barbell','بار حديد','Stand with the bar in front of your thighs, feet about hip-width apart, and knees softly bent. Brace your torso, push your hips back, and keep the bar close to your legs as you lower it under control. Stop when you feel a comfortable hamstring stretch, then drive your hips forward to stand tall.','','upper legs','strength','',NULL,'upper legs','upper legs','Hamstrings, Glutes'),
('wger-512',NULL,'Seated Cable Row — Narrow Grip','','Cable machine','جهاز كابل','Sit at the cable row with your feet braced and hold the narrow handle. Keep your torso upright, pull the handle toward your lower ribs, and draw your shoulder blades back without leaning far behind you. Extend your arms again under control.','','back','strength','',NULL,'back','back','Lats'),
('wger-537',NULL,'Incline Dumbbell Bench Press','','Dumbbell, Incline bench','دمبل، مقعد مائل','This is a variation of the flat bench press designed to emphasize the clavicular head of the pectoralis major (the upper portion). By tilting the torso, the angle of the push changes, shifting more tension to the upper chest and shoulders, which helps achieve a more aesthetic, balanced, and three-dimensional development of the torso. Bench Adjustment and Preparation: Set the bench to an incline of between 30 and 45 degrees (an incline greater than 45° will place too much strain on the shoulders and reduce the stimulus to the chest). Sit down with a dumbbell on each thigh. Starting position: Lean back, resting your back against the bench, while using your knees one after the other to push the dumbbells upward to shoulder height. Anatomical Stabilization: Plant your feet firmly on the floor. Retract your scapulas (bring your shoulder blades together and press them into the bench) to protect your shoulders and stabilize the load. Eccentric Phase (Lowering): Lower the dumbbells slowly and in a controlled manner toward the upper part of your chest. Your elbows should not splay out to the sides (90°); maintain a safe angle of about 45 to 60 degrees relative to your torso. Concentric Phase (Lift): Push the dumbbells vertically upward as you exhale. Follow a slightly converging path (without letting them touch at the top). Stop the movement just before locking out your elbows to maintain muscle tension in the upper pectoral.','','chest','strength','',NULL,'chest','chest','Chest'),
('wger-538',NULL,'Incline Barbell Bench Press','','Barbell, Incline bench','بار حديد، مقعد مائل','Set the bench to a moderate incline and lie back with your feet planted. Grip the bar slightly wider than shoulder-width, unrack it, and lower it under control toward your upper chest. Press the bar upward over your shoulders, then repeat with the bar path controlled. Use rack safeties or a spotter for challenging loads.','','chest','strength','',NULL,'chest','chest','Chest'),
('wger-543',NULL,'Machine Shoulder Press','','Shoulder press machine','جهاز ضغط الكتفين','Sit in the machine with your feet about shoulder-width apart and your back upright against the support. Grip the handles or bar at shoulder height. Press upward until your arms are extended, then lower slowly to the starting position and repeat.','','shoulders','strength','',NULL,'shoulders','shoulders','Shoulders'),
('wger-567',NULL,'Seated Dumbbell Shoulder Press','','Bench, Dumbbell','مقعد، دمبل','Sit on a bench, the back rest should be almost vertical. Take two dumbbells and bring them up to shoulder height, the palms and the elbows point during the whole exercise to the front. Press the weights up, at the highest point they come very near but don''t touch. Go slowly down and repeat.','','shoulders','strength','',NULL,'shoulders','shoulders','Shoulders'),
('wger-570',NULL,'Cable Shoulder Shrug','','Cable machine','جهاز كابل','Stand upright holding the low cable handles at your sides with your arms straight. Lift your shoulders toward your ears without bending your elbows or rocking your torso. Pause briefly, then lower your shoulders under control.','','shoulders','strength','',NULL,'shoulders','shoulders','Trapezius'),
('wger-575',NULL,'Smith Machine Shrug','','Smith machine','جهاز سميث','Grip the Smith machine bar and stand about shoulder-width apart with your knees slightly bent and your gaze forward. Keep your arms straight at your sides. Raise the weight by lifting your shoulders without bending your elbows. Pause at the top for one or two seconds, then lower your shoulders slowly.','','shoulders','strength','',NULL,'shoulders','shoulders','Shoulders'),
('wger-584',NULL,'Single-Arm Dumbbell Preacher Curl','','Dumbbell, Preacher bench','دمبل، مقعد بريتشر','Sit on the preacher curl bench and perform a bicep curl with a dumbbell in one hand. Your other hand can be at rest, or beneath your curling arm''s elbow.','','upper arms','strength','',NULL,'upper arms','upper arms','Biceps'),
('wger-590',NULL,'Seated Calf Raise Machine','','Seated calf raise machine','جهاز رفع السمانة جالسًا','Sit on a bench for calf raises and check that the feet are half free and that you can completely stretch the calf muscles down. Pull your calves up, going as far (up) as you can. Make at the highest point a short pause of 1 or 2 seconds and go down.','','lower legs','strength','',NULL,'lower legs','lower legs','Soleus'),
('wger-622',NULL,'Standing Calf Raise on Step','','Step','درجة مرتفعة','Stand with the balls of your feet on the edge of a stable step and use the rail lightly for balance. Lower your heels under control, then press through the balls of your feet to rise as high as comfortable. Pause briefly and lower again without bouncing.','','lower legs','strength','',NULL,'lower legs','lower legs','Calves'),
('wger-655',NULL,'Tricep Dumbbell Kickback','','Dumbbell','دمبل','Start with a dumbbell in each hand and your palms facing your torso. Keep your back straight with a slight bend in the knees and bend forward at the waist. Your torso should be almost parallel to the floor. Make sure to keep your head up. Your upper arms should be close to your torso and parallel to the floor. Your forearms should be pointed towards the floor as you hold the weights. There should be a 90-degree angle formed between your forearm and upper arm. This is your starting position. Now, while keeping your upper arms stationary, exhale and use your triceps to lift the weights until the arm is fully extended. Focus on moving the forearm. After a brief pause at the top contraction, inhale and slowly lower the dumbbells back down to the starting position. Repeat the movement for the prescribed amount of repetitions. Variations: This exercise can be executed also one arm at a time much like the one arm rows are performed. Also, if you like the one arm variety, you can use a low pulley handle instead of a dumbbell for better peak contraction. In this case, the palms should be facing up (supinated grip) as opposed to the torso (neutral grip).','','upper arms','strength','',NULL,'upper arms','upper arms','Triceps'),
('wger-659',NULL,'Overhead Cable Triceps Extension','','Cable machine','جهاز كابل','Face away from a high cable with the rope held behind your head. Keep your upper arms steady beside your head and extend your elbows until your arms are straight. Pause briefly, then bend your elbows to return under control.','','upper arms','strength','',NULL,'upper arms','upper arms','Triceps'),
('wger-802',NULL,'Barbell Lunges Walking','','Barbell','بار حديد','Place the bar across your upper back and stand with your feet about hip-width apart, leaving a clear path ahead. Take a long step forward and lower your hips under control until the rear knee is close to the floor and the front knee is near 90 degrees. Drive through the front heel and bring the rear leg forward into the next lunge. Continue alternating legs while keeping your torso upright and your abdomen braced.','','upper legs','strength','',NULL,'upper legs','upper legs','Glutes, Quads'),
('wger-803',NULL,'Single-Arm Overhead Cable Triceps Extension','','Cable machine','جهاز كابل','Face away from the cable and hold the handle behind your head with one elbow pointing upward. Keep your upper arm steady, extend the elbow until the arm is straight, then return under control. Complete the set before changing sides.','','upper arms','strength','',NULL,'upper arms','upper arms','Triceps')
